#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <optional>
#include <vector>

struct Record
{
    std::int32_t id{};
    std::int32_t stock{};
    double price{};
};

bool writeRecords(const std::filesystem::path& file, const std::vector<Record>& records)
{
    std::ofstream out{ file, std::ios::binary };
    if (!out)
    {
        return false;
    }
    for (const Record& record : records)
    {
        out.write(reinterpret_cast<const char*>(&record), sizeof(Record));
    }
    return static_cast<bool>(out);
}

std::size_t recordCount(const std::filesystem::path& file)
{
    std::error_code error{};
    const auto size{ std::filesystem::file_size(file, error) };
    return error ? 0 : static_cast<std::size_t>(size / sizeof(Record));
}

std::optional<Record> readRecord(const std::filesystem::path& file, std::size_t index)
{
    if (index >= recordCount(file))
    {
        return std::nullopt;
    }
    std::ifstream in{ file, std::ios::binary };
    in.seekg(static_cast<std::streamoff>(index * sizeof(Record)));
    Record record{};
    if (!in.read(reinterpret_cast<char*>(&record), sizeof(Record)))
    {
        return std::nullopt;
    }
    return record;
}

