namespace fs = std::filesystem;
struct TempFile { fs::path path{ "xenon_records_test.bin" }; TempFile() { fs::remove(path); } ~TempFile() { std::error_code ec; fs::remove(path, ec); } };
std::vector<Record> sample() { return { { 1, 10, 2.5 }, { 2, 0, 19.99 }, { 3, 250, 0.1 }, { 4, 7, 1000.0 } }; }

TEST("writes fixed-size records") { TempFile t; CHECK(writeRecords(t.path, sample())); CHECK_EQ(fs::file_size(t.path), 4 * sizeof(Record)); CHECK_EQ(recordCount(t.path), 4u); }
TEST("reads any record directly") { TempFile t; writeRecords(t.path, sample()); const auto r{ readRecord(t.path, 2) }; CHECK(r.has_value()); if (r) { CHECK_EQ(r->id, 3); CHECK_EQ(r->stock, 250); CHECK_NEAR(r->price, 0.1, 1e-12); } const auto first{ readRecord(t.path, 0) }; CHECK(first && first->id == 1); const auto last{ readRecord(t.path, 3) }; CHECK(last && last->id == 4); }
TEST("out of range and missing files") { TempFile t; writeRecords(t.path, sample()); CHECK(!readRecord(t.path, 4)); CHECK(!readRecord("xenon_no_such_file.bin", 0)); CHECK_EQ(recordCount("xenon_no_such_file.bin"), 0u); }

